"""Yahoo の月次 adjclose を harness.yahoo と同じ取り方で取る（キャッシュは scratchpad だけ）。
events=div|split|capitalGain も一緒に取り、配当の記録と adjclose の整合を検査できるようにする。"""
import os, json, time, datetime, urllib.request
SP = os.path.dirname(os.path.abspath(__file__))
CD = os.path.join(SP, 'yh_ivf_only')
UA = {'User-Agent': 'Mozilla/5.0 (ccf-gate research)'}
os.makedirs(CD, exist_ok=True)

def raw(sym, days=3):
    p = os.path.join(CD, sym + '.json')
    if os.path.exists(p) and time.time() - os.path.getmtime(p) < days * 86400 and os.path.getsize(p) > 200:
        return json.load(open(p))
    url = (f'https://query1.finance.yahoo.com/v8/finance/chart/{sym}?period1=0&period2={int(time.time())}'
           f'&interval=1mo&events=div%7Csplit%7CcapitalGain')
    for a in range(3):
        try:
            b = urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=40).read()
            j = json.loads(b)
            json.dump(j, open(p, 'w'))
            time.sleep(0.6)
            return j
        except urllib.error.HTTPError as e:
            if e.code in (400, 404):
                json.dump({'chart': {'result': None, 'error': str(e.code)}}, open(p, 'w'))
                return None
            time.sleep(3 * (a + 1))
        except Exception:
            time.sleep(3 * (a + 1))
    return None

def monthly(sym):
    """→ dict(adj={YYYYMM: adjclose}, close={YYYYMM: close}, divs=[(YYYYMMDD, amt)], meta) or None"""
    j = raw(sym)
    try:
        res = j['chart']['result'][0]
    except Exception:
        return None
    if not res or not res.get('timestamp'):
        return None
    ind = res['indicators']
    adj = (ind.get('adjclose') or [{}])[0].get('adjclose')
    cl = ind['quote'][0]['close']
    gmt = (res.get('meta') or {}).get('gmtoffset') or 0
    A, C = {}, {}
    for t, a, c in zip(res['timestamp'], adj or cl, cl):
        d = datetime.datetime.utcfromtimestamp(t + gmt)
        k = d.year * 100 + d.month
        if a is not None:
            A[k] = float(a)
        if c is not None:
            C[k] = float(c)
    dv = []
    for v in (res.get('events') or {}).get('dividends', {}).values():
        d = datetime.datetime.utcfromtimestamp(v['date'] + gmt)
        dv.append((d.year * 10000 + d.month * 100 + d.day, v['amount']))
    cg = []
    for v in (res.get('events') or {}).get('capitalGains', {}).values():
        d = datetime.datetime.utcfromtimestamp(v['date'] + gmt)
        cg.append((d.year * 10000 + d.month * 100 + d.day, v['amount']))
    m = res.get('meta') or {}
    return {'adj': A, 'close': C, 'divs': sorted(dv), 'cg': sorted(cg), 'has_adj': adj is not None,
            'meta': {'type': m.get('instrumentType'), 'ccy': m.get('currency'), 'name': m.get('longName') or m.get('shortName'),
                     'first': min(A) if A else None, 'last': max(A) if A else None}}

