import sys, os, math, statistics as S
SP = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, SP)
from funds import *

def qc(sym):
    x = yf.monthly(sym)
    if not x:
        return {'sym': sym, 'error': '取れない'}
    A, C = x['adj'], x['close']
    ks = sorted(A)
    miss = [m for m in h.month_range(ks[0], ks[-1]) if m not in A]
    r = h.px_to_ret(A)
    big = [(m, round(v * 100, 1)) for m, v in r.items() if abs(v) > 0.35]
    # adj/close の比の変化（配当の調整）を年ごとに
    yr_adj, yr_div = {}, {}
    for a, b in zip(ks, ks[1:]):
        if a in C and b in C and C[a] and C[b]:
            f = (A[b] / C[b]) / (A[a] / C[a])
            yr_adj[b // 100] = yr_adj.get(b // 100, 0) + math.log(f)
    for dd, amt in x['divs']:
        m = dd // 100
        prev = h.add_months(m, -1)
        p = C.get(prev) or C.get(m)
        if p:
            yr_div[dd // 10000] = yr_div.get(dd // 10000, 0) + amt / p
    full = [y for y in range(ks[0] // 100 + 1, ks[-1] // 100)]
    nodiv = [y for y in full if yr_div.get(y, 0) == 0]
    adj_no = [y for y in full if abs(yr_adj.get(y, 0)) < 1e-4]
    return {'sym': sym, 'first': ks[0], 'last': ks[-1], 'missing_months': len(miss), 'big_moves': big[:6],
            'years_without_div_event': nodiv, 'years_adj_flat': adj_no,
            'mean_div_yield_events': round(S.mean([yr_div.get(y, 0) for y in full]) * 100, 2) if full else None,
            'mean_div_yield_adj': round(S.mean([yr_adj.get(y, 0) for y in full]) * 100, 2) if full else None}

if __name__ == '__main__':
    for s in ALL:
        q = qc(s)
        flag = '  ←要注意' if (q.get('missing_months') or q.get('big_moves') or q.get('years_without_div_event') or q.get('years_adj_flat')) else ''
        print(q, flag)

