def ex(a, b, lo, hi):
    ms = [m for m in sorted(set(a) & set(b)) if lo <= m <= hi]
    if len(ms) < 12:
        return None
    g1 = math.prod(1 + a[m] for m in ms) ** (12 / len(ms)) - 1
    g2 = math.prod(1 + b[m] for m in ms) ** (12 / len(ms)) - 1
    e = [a[m] - b[m] for m in ms]
    t = S.mean(e) / (S.stdev(e) / math.sqrt(len(e)))
    return f"{(g1-g2)*100:+.2f} (t{t:.2f}, {len(ms)}m)"

